#pragma once

#include "common.h"

// DWARF register numbers
#include "libunwind/libunwind.h"

// Unwind rules that apply to a managed frame after its prolog, generated by ILC instead of
// a DWARF FDE. Keep in sync with CompactUnwindTableNode in ILCompiler.
struct CompactUnwindDescriptor
{
    // The return address was signed with the A key and the CFA as modifier (arm64 pac-ret)
    static const uint8_t FlagReturnAddressSigned = 0x01;
    // The saved registers are WideSavedRegister instead of SavedRegister
    static const uint8_t FlagWideSlots = 0x02;
    // The saved registers are described by a RegisterRun, and RegisterCount is 0
    static const uint8_t FlagRegisterRun = 0x04;
    // The registers of the run are saved in descending register order
    static const uint8_t FlagRunDescending = 0x08;

    static const uint8_t NoRegister = 0xFF;

    uint8_t CfaRegister;
    uint8_t RegisterCount;
    uint8_t Flags;
    uint8_t Reserved;
    uint32_t PrologSize;
    int32_t CfaOffset;

    // The register is saved at CFA - Slot * sizeof(void*)
    struct SavedRegister
    {
        uint16_t Register;
        uint16_t Slot;
    };

    struct WideSavedRegister
    {
        uint16_t Register;
        uint16_t Reserved;
        uint32_t Slot;
    };

    // The return address register is saved at ReturnAddressSlot, or stays in its register when that is 0,
    // ExtraRegister at ExtraSlot unless it is NoRegister, and the registers of RegisterMask (DWARF numbers
    // 0-31) at consecutive slots from FirstSlot in ascending, or with FlagRunDescending descending, order
    struct RegisterRun
    {
        uint8_t ReturnAddressSlot;
        uint8_t ExtraRegister;
        uint8_t ExtraSlot;
        uint8_t FirstSlot;
        uint32_t RegisterMask;
    };

    const RegisterRun* GetRegisterRun() const
    {
        return (const RegisterRun*)(this + 1);
    }

    void GetSavedRegister(uint32_t index, int* pRegister, uint32_t* pSlot) const
    {
        if ((Flags & FlagWideSlots) != 0)
        {
            const WideSavedRegister* pSaved = (const WideSavedRegister*)(this + 1) + index;
            *pRegister = pSaved->Register;
            *pSlot = pSaved->Slot;
        }
        else
        {
            const SavedRegister* pSaved = (const SavedRegister*)(this + 1) + index;
            *pRegister = pSaved->Register;
            *pSlot = pSaved->Slot;
        }
    }

    uint32_t GetSize() const
    {
        if ((Flags & FlagRegisterRun) != 0)
            return sizeof(CompactUnwindDescriptor) + sizeof(RegisterRun);

        return sizeof(CompactUnwindDescriptor) + RegisterCount *
            ((Flags & FlagWideSlots) != 0 ? sizeof(WideSavedRegister) : sizeof(SavedRegister));
    }
};

class UnwindHelpers
{
public:
    static bool StepFrame(REGDISPLAY *regs, const CompactUnwindDescriptor *pDescriptor);
};
